package main

// Sweep lane sweep/s10-panics (2026-10-27), shape S10: the nil receiver at
// the sites BUG-063 (the implicit `&*q` receiver) did not pin — a VALUE
// method through a nil pointer in defer and go position (the receiver is
// evaluated at the statement: spec#Defer_statements, #Go_statements), the
// method expression `T.V(*p)` (the argument dereferences), the pointer
// method expression `(*T).V(p)` over a value method (gc's autogenerated
// wrapper: the panicwrap text, S12's), and the receiver reached through a
// struct field holding nil.

type rsVal struct{ n int }

func (v rsVal) V() int { return v.n + 1 }

type rsHolder struct{ p *rsVal }

// The deferred call's receiver *p is evaluated at the defer statement: the
// panic is raised there, the statement after it never runs. gc: 100.
func deferValueRecvNil() int {
	var p *rsVal
	r := 0
	count := 0
	func() {
		defer func() {
			if recover() != nil {
				r = 100
			}
		}()
		defer p.V()
		count = 1
	}()
	return r + count
}

// The go statement evaluates the receiver in the parent: the panic is the
// parent's, recoverable there, and nothing is spawned. gc: 100.
func goValueRecvNil() int {
	var p *rsVal
	r := 0
	func() {
		defer func() {
			if recover() != nil {
				r = 100
			}
		}()
		go p.V()
	}()
	return r
}

func methodExprDerefArg() int {
	var p *rsVal
	f := rsVal.V
	return f(*p)
}

func ptrMethodExprValueRecvNil() int {
	var p *rsVal
	f := (*rsVal).V
	return f(p)
}

func fieldPtrValueRecvNil() int {
	h := rsHolder{}
	return h.p.V()
}

